function Button({ onClick, children, disabled }) {
  const [loading, setLoading] = useState(false);
  
  const handleClick = async () => {
    setLoading(true);
    await onClick();
    setLoading(false);
  };

  return (
    <button 
      onClick={handleClick}
      disabled={disabled || loading}
      className="bg-blue-500 hover:bg-blue-700"
    >
      {loading ? 'Loading...' : children}
    </button>
  );
}

